export const queue = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Front desk queue</title>\n<style>\n:root{--bg:#fafaf7;--card:#fff;--ink:#1d2433;--mut:#667;--line:#e3e5ea;--warn:#b3261e;--ok:#1b6e4a}\n@media(prefers-color-scheme:dark){:root{--bg:#14161b;--card:#1c1f26;--ink:#e8eaf0;--mut:#9aa3b2;--line:#2c313b;--warn:#f2827a;--ok:#6fcf9f}}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 -apple-system,Segoe UI,Helvetica,Arial,sans-serif}\nmain{max-width:860px;margin:0 auto;padding:20px 16px 60px}h1{font-size:22px;margin:0 0 4px}.sub{color:var(--mut);margin-bottom:20px}\nh2{font-size:15px;margin:26px 0 8px;display:flex;gap:8px;align-items:center}.n{background:var(--warn);color:#fff;border-radius:10px;padding:0 8px;font-size:12px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin:8px 0;display:flex;gap:12px;justify-content:space-between;align-items:flex-start}\n.t{font-weight:600}.m{color:var(--mut);font-size:13px}button{font:inherit;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:8px;padding:6px 12px;cursor:pointer}\n.empty{color:var(--mut);padding:8px 0}a{color:inherit}\n</style></head><body><main>\n<h1>Front desk queue</h1><div class=\"sub\">Things to do now. Open <a href=\"/calendar\">the designer calendars</a>.</div>\n<div id=\"out\">Loading…</div></main>\n<script>\nconst key=localStorage.getItem('key')||prompt('Access key');localStorage.setItem('key',key||'');\nconst api=(p,o={})=>fetch(p,{...o,headers:{'x-api-key':key,'content-type':'application/json'}}).then(r=>r.json());\nconst esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst when=d=>new Date(d).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'});\nfunction sec(title,rows,render,btn){return `<h2>${title}<span class=\"n\" ${rows.length?'':'style=\"background:var(--ok)\"'}>${rows.length}</span></h2>`+(rows.length?rows.map(r=>`<div class=\"card\"><div>${render(r)}</div>${btn?`<button data-id=\"${r.id}\" data-a=\"${btn[1]}\">${btn[0]}</button>`:''}</div>`).join(''):'<div class=\"empty\">Nothing waiting.</div>')}\nasync function load(){\n const q=await api('/api/queue');if(q.error){document.getElementById('out').textContent='Access key not accepted. Clear it and reload.';localStorage.removeItem('key');return}\n document.getElementById('out').innerHTML=\n sec('Escalations: call back within 15 minutes',q.escalations,r=>`<div class=\"t\">${esc(r.caller_name||'Caller')} · ${esc(r.caller_phone||'no number')}</div><div class=\"m\">${when(r.created_at)} · ${esc(r.summary||'')}</div>`,['Done','done'])+\n sec('Callbacks owed (missed or dropped calls)',q.callbacks,r=>`<div class=\"t\">${esc(r.caller_phone||'no number')}</div><div class=\"m\">${when(r.created_at)}</div>`,['Done','done'])+\n sec('Declined calls to review',q.declines,r=>`<div class=\"t\">${esc(r.caller_name||'Caller')} · ${esc(r.area||'')}</div><div class=\"m\">${when(r.created_at)} · Reason: ${esc(r.decline_reason||'')}</div><div class=\"m\">${esc(r.summary||'')}</div>`,['Reviewed','reviewed'])+\n sec('Bookings at risk (call-by time passed or no slot in window)',q.lateBookings,r=>`<div class=\"t\">${esc(r.caller_name||'Lead')} · ${esc(r.designer)} · ${esc(r.tier)}</div><div class=\"m\">Call by ${when(r.call_by)}</div>`,['Done','done']);\n}\ndocument.addEventListener('click',async e=>{const b=e.target.closest('button[data-id]');if(!b)return;b.disabled=true;await api('/api/review',{method:'POST',body:JSON.stringify({id:Number(b.dataset.id),action:b.dataset.a})});load()});\nload();setInterval(load,15000);\n</script></body></html>\n";
export const calendar = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Designer calendars</title>\n<style>\n:root{--bg:#fafaf7;--card:#fff;--ink:#1d2433;--mut:#667;--line:#e3e5ea;--hot:#b3261e;--pri:#a15c00;--std:#1b6e4a}\n@media(prefers-color-scheme:dark){:root{--bg:#14161b;--card:#1c1f26;--ink:#e8eaf0;--mut:#9aa3b2;--line:#2c313b;--hot:#f2827a;--pri:#f0b45c;--std:#6fcf9f}}\nbody{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 -apple-system,Segoe UI,Helvetica,Arial,sans-serif}\nmain{max-width:1000px;margin:0 auto;padding:20px 16px 60px}h1{font-size:22px;margin:0 0 4px}.sub{color:var(--mut);margin-bottom:16px}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:10px}\n.d{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 12px}.d.next{outline:2px solid var(--std)}\n.d h3{margin:0 0 6px;font-size:15px;display:flex;justify-content:space-between}.tag{font-size:11px;color:var(--std);font-weight:600}\n.b{border-left:3px solid var(--std);padding:2px 8px;margin:5px 0}.b.hot{border-color:var(--hot)}.b.priority{border-color:var(--pri)}.m{color:var(--mut);font-size:12px}.empty{color:var(--mut);font-size:13px}a{color:inherit}\n</style></head><body><main>\n<h1>Designer calendars</h1><div class=\"sub\">One calendar per designer. The next lead goes to the highlighted designer. <a href=\"/queue\">Front desk queue</a></div>\n<div class=\"grid\" id=\"g\">Loading…</div></main>\n<script>\nconst key=localStorage.getItem('key')||prompt('Access key');localStorage.setItem('key',key||'');\nconst esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst when=d=>new Date(d).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',weekday:'short',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'});\nasync function load(){\n const r=await fetch('/api/calendar',{headers:{'x-api-key':key}}).then(r=>r.json());\n if(r.error){document.getElementById('g').textContent='Access key not accepted. Clear it and reload.';localStorage.removeItem('key');return}\n document.getElementById('g').innerHTML=r.designers.map((d,i)=>{\n  const bs=r.bookings.filter(b=>b.designer_id===d.id);\n  return `<div class=\"d ${i===r.next_designer_index?'next':''}\"><h3>${esc(d.name)}<span class=\"tag\">${i===r.next_designer_index?'NEXT LEAD':''}</span></h3>`+\n  (bs.length?bs.map(b=>`<div class=\"b ${esc(b.tier)}\"><div>${when(b.start_at)}</div><div class=\"m\">${esc(b.caller_name||'Lead')} · ${esc(b.area||'')} · ${esc(b.tier)}${b.status!=='new'?' · '+esc(b.status):''}</div></div>`).join(''):'<div class=\"empty\">Free this week</div>')+'</div>'}).join('');\n}\nload();setInterval(load,10000);\n</script></body></html>\n";
